// ============================================
// CALCULATE 48H WINDOW
// Saves everything to static data
// so HTTP nodes cannot lose it
// ============================================

const rawInput    = $input.first().json;
const rawCategory = rawInput.category || '';
const catTrimmed  = rawCategory.trim();
const catLower    = catTrimmed.toLowerCase();
const email       = rawInput.email || 'jeyaalagappan@gmail.com';

console.log('Input category:', rawCategory);
console.log('Input text:', rawInput.text);

// ============================================
// NORMALIZE CATEGORY
// ============================================
let cat = '';

if (catLower === 'sports' || catLower === 'sport') {
  cat = 'Sports';
} else if (
  catLower === 'artificial intelligence' ||
  catLower === 'ai'
) {
  cat = 'Artificial Intelligence';
} else if (
  catLower === 'geopolitics' ||
  catLower === 'geo'         ||
  catLower === 'world'
) {
  cat = 'Geopolitics';
} else {
  // Try from raw text field directly
  const textLower = (rawInput.text || '').toLowerCase().trim();
  if (textLower.includes('sport'))                                    cat = 'Sports';
  else if (textLower.includes('ai') || textLower.includes('artif'))  cat = 'Artificial Intelligence';
  else if (textLower.includes('geo') || textLower.includes('world')) cat = 'Geopolitics';
  else cat = catTrimmed;
}

console.log('Normalized category:', cat);

// ============================================
// TIME WINDOW
// ============================================
const now      = new Date();
const minus48h = new Date(now.getTime() - 48 * 60 * 60 * 1000);

const iso48h       = minus48h.toISOString();
const gnewsFrom    = iso48h.split('.')[0];
const guardianFrom = minus48h.toISOString().split('T')[0];
const newsapiFrom  = minus48h.toISOString().split('T')[0];

// ============================================
// KEYWORD MAP
// ============================================
const categoryMap = {
  'Geopolitics': {
    gnews:           'geopolitics',
    newsapi:         'geopolitics world politics',
    guardianSection: 'world',
    guardian:        'geopolitics world politics',
    pexels:          'world politics globe'
  },
  'Sports': {
    gnews:           'sports',
    newsapi:         'sports',
    guardianSection: 'sport',
    guardian:        'sport',
    pexels:          'sports stadium action'
  },
  'Artificial Intelligence': {
    gnews:           'artificial intelligence',
    newsapi:         'artificial intelligence',
    guardianSection: 'technology',
    guardian:        'artificial intelligence',
    pexels:          'artificial intelligence technology'
  }
};

const keywords = categoryMap[cat] || {
  gnews:           cat,
  newsapi:         cat,
  guardianSection: 'world',
  guardian:        cat,
  pexels:          cat + ' news'
};

const gnewsKeyword    = keywords.gnews;
const newsapiKeyword  = keywords.newsapi;
const guardianSection = keywords.guardianSection;
const guardianKeyword = keywords.guardian;
const pexelsKeyword   = keywords.pexels;

console.log('Keywords set - pexels:', pexelsKeyword);

// ============================================
// SAVE TO STATIC DATA
// HTTP nodes eat input data
// Static data survives everything
// ============================================
const staticData              = $getWorkflowStaticData('global');
staticData.category           = cat;
staticData.email              = email;
staticData.pexelsKeyword      = pexelsKeyword;
staticData.cutoffTimestamp    = minus48h.getTime();
staticData.gnewsFrom          = gnewsFrom;
staticData.guardianFrom       = guardianFrom;
staticData.newsapiFrom        = newsapiFrom;
staticData.gnewsKeyword       = gnewsKeyword;
staticData.newsapiKeyword     = newsapiKeyword;
staticData.guardianSection    = guardianSection;
staticData.guardianKeyword    = guardianKeyword;

console.log('Saved to static data:');
console.log('  category:', staticData.category);
console.log('  pexelsKeyword:', staticData.pexelsKeyword);
console.log('  cutoffTimestamp:', new Date(staticData.cutoffTimestamp).toISOString());

// ============================================
// RETURN FOR HTTP NODES
// ============================================
return [{
  json: {
    ...rawInput,
    category:        cat,
    email,
    now:             now.toISOString(),
    from48h:         iso48h,
    gnewsFrom,
    guardianFrom,
    newsapiFrom,
    cutoffTimestamp: minus48h.getTime(),
    keywords,
    gnewsKeyword,
    newsapiKeyword,
    guardianSection,
    guardianKeyword,
    pexelsKeyword
  }
}];

// ============================================
// NORMALIZE & DEDUPLICATE
// Uses global static data for metadata
// No need to search inputs for category
// ============================================

const allInputs = $input.all();
console.log('Total inputs:', allInputs.length);

// ============================================
// STEP 1 - READ FROM GLOBAL STATIC DATA
// Single source of truth for all metadata
// Always available regardless of HTTP nodes
// ============================================
const staticData      = $getWorkflowStaticData('global');
const category        = staticData.category        || '';
const email           = staticData.email           || 'jeyaalagappan@gmail.com';
const cutoffTimestamp = staticData.cutoffTimestamp || (Date.now() - 48 * 3600 * 1000);
const pexelsKeyword   = staticData.pexelsKeyword   || '';

console.log('category:', category);
console.log('email:', email);
console.log('pexelsKeyword:', pexelsKeyword);
console.log('cutoff:', new Date(cutoffTimestamp).toISOString());

// ============================================
// STEP 2 - IDENTIFY EACH API INPUT
// Pexels  → { photos: [] }
// Guardian→ { response: { results: [] } }
// NewsAPI → { articles: [{ urlToImage }] }
// GNews   → { articles: [{ image }] }
// ============================================
let gnewsRaw     = [];
let newsapiRaw   = [];
let guardianRaw  = [];
let pexelsPhotos = [];

for (const input of allInputs) {
  const j     = input?.json || {};
  const first = j.articles?.[0] || {};

  if (j.photos && Array.isArray(j.photos)) {
    pexelsPhotos = j.photos;
    console.log('Found Pexels:', pexelsPhotos.length);

  } else if (j.response && j.response.results) {
    guardianRaw = j.response.results;
    console.log('Found Guardian:', guardianRaw.length);

  } else if (j.articles && Array.isArray(j.articles)) {
    if (
      first.urlToImage !== undefined ||
      first.source?.id !== undefined
    ) {
      newsapiRaw = j.articles;
      console.log('Found NewsAPI:', newsapiRaw.length);
    } else {
      gnewsRaw = j.articles;
      console.log('Found GNews:', gnewsRaw.length);
    }
  }
}

// ============================================
// STEP 3 - PROCESS PEXELS IMAGES
// ============================================
const fallbackImg = {
  url:          'https://placehold.co/800x400/1a1a2e/ffffff?text=' +
                 encodeURIComponent(category || 'Newsletter'),
  alt:          category + ' Newsletter',
  photographer: ''
};

const pexelsImages = pexelsPhotos.map(p => ({
  url:          p.src?.large || p.src?.medium || '',
  alt:          p.alt        || category,
  photographer: p.photographer || ''
}));

const images = {
  hero:     pexelsImages[0] || fallbackImg,
  section1: pexelsImages[1] || fallbackImg,
  section2: pexelsImages[2] || fallbackImg
};

console.log('Hero:', images.hero.url);
console.log('Section1:', images.section1.url);
console.log('Section2:', images.section2.url);

// ============================================
// STEP 4 - NORMALIZE GNEWS
// ============================================
const gnewsNorm = gnewsRaw.map(a => ({
  title:       a.title        || '',
  description: a.description  || '',
  url:         a.url          || '',
  publishedAt: a.publishedAt  || '',
  source:      a.source?.name || 'GNews',
  image:       a.image        || null,
  timestamp:   new Date(a.publishedAt || 0).getTime()
}));

// ============================================
// STEP 5 - NORMALIZE NEWSAPI
// ============================================
const newsapiNorm = newsapiRaw.map(a => ({
  title:       a.title        || '',
  description: a.description  || '',
  url:         a.url          || '',
  publishedAt: a.publishedAt  || '',
  source:      a.source?.name || 'NewsAPI',
  image:       a.urlToImage   || null,
  timestamp:   new Date(a.publishedAt || 0).getTime()
}));

// ============================================
// STEP 6 - NORMALIZE GUARDIAN
// ============================================
const guardianNorm = guardianRaw.map(a => ({
  title:       a.webTitle           || '',
  description: a.fields?.trailText  || '',
  url:         a.webUrl             || '',
  publishedAt: a.webPublicationDate || '',
  source:      'The Guardian',
  image:       a.fields?.thumbnail  || null,
  timestamp:   new Date(a.webPublicationDate || 0).getTime()
}));

console.log('GNews normalized:', gnewsNorm.length);
console.log('NewsAPI normalized:', newsapiNorm.length);
console.log('Guardian normalized:', guardianNorm.length);

// ============================================
// STEP 7 - MERGE NEWS ARTICLES
// ============================================
let all = [...gnewsNorm, ...newsapiNorm, ...guardianNorm];
console.log('Total merged:', all.length);

// ============================================
// STEP 8 - FILTER 48 HOURS
// ============================================
all = all.filter(a => {
  const valid = a.timestamp >= cutoffTimestamp;
  if (!valid) console.log('Removed old:', a.publishedAt, a.title?.slice(0, 30));
  return valid;
});
console.log('After 48h filter:', all.length);

// ============================================
// STEP 9 - DEDUPLICATE BY URL
// ============================================
const seen = new Set();
all = all.filter(a => {
  if (!a.url || seen.has(a.url)) return false;
  seen.add(a.url);
  return true;
});
console.log('After dedupe:', all.length);

// ============================================
// STEP 10 - CLEAN BAD ARTICLES
// ============================================
all = all.filter(a =>
  a.title                 &&
  a.title !== '[Removed]' &&
  a.title !== 'null'      &&
  a.title.trim() !== ''   &&
  a.url                   &&
  a.url.trim() !== ''
);
console.log('After clean:', all.length);

// ============================================
// STEP 11 - SORT NEWEST FIRST
// ============================================
all.sort((a, b) => b.timestamp - a.timestamp);

// ============================================
// STEP 12 - TOP 10
// ============================================
all = all.slice(0, 10);
console.log('Final count:', all.length);

// ============================================
// STEP 13 - NO ARTICLES FOUND
// ============================================
if (all.length === 0) {
  return [{
    json: {
      error:        'NO_ARTICLES',
      articleCount: 0,
      category,
      email,
      pexelsKeyword,
      images,
      diagnostic: {
        gnewsCount:    gnewsNorm.length,
        newsapiCount:  newsapiNorm.length,
        guardianCount: guardianNorm.length,
        pexelsCount:   pexelsPhotos.length,
        cutoffTime:    new Date(cutoffTimestamp).toISOString()
      }
    }
  }];
}

// ============================================
// STEP 14 - RETURN EVERYTHING
// Articles + Images + Category
// Ready for LLM directly
// ============================================
console.log('SUCCESS:', all.length, 'articles | category:', category);

return [{
  json: {
    articles:     all,
    articleCount: all.length,
    category,
    email,
    pexelsKeyword,
    images,
    sources: {
      gnews:    gnewsNorm.length,
      newsapi:  newsapiNorm.length,
      guardian: guardianNorm.length,
      pexels:   pexelsPhotos.length
    },
    debug: {
      cutoffTime:   new Date(cutoffTimestamp).toISOString(),
      totalFetched: gnewsNorm.length + newsapiNorm.length + guardianNorm.length,
      finalCount:   all.length,
      category,
      pexelsKeyword,
      heroImage:    images.hero.url
    }
  }
}];

// ============================================
// CREATE HTML ATTACHMENT
// Reads category/email from static data
// No node name references
// ============================================

const llmOutput = $input.first().json;

// ============================================
// STEP 1 - EXTRACT HTML FROM LLM RESPONSE
// Different OpenAI node versions return
// html in different places
// ============================================
const html =
  llmOutput?.message?.content               ||
  llmOutput?.choices?.[0]?.message?.content ||
  llmOutput?.text                            ||
  llmOutput?.content                         ||
  '';

console.log('HTML length:', html.length);
console.log('First 50 chars:', html.slice(0, 50));

// ============================================
// STEP 2 - VALIDATE HTML
// ============================================
if (!html || html.length < 100) {
  return [{
    json: {
      error:     'LLM_FAILED',
      message:   'LLM returned empty or invalid HTML',
      rawLength: html.length,
      raw:       JSON.stringify(llmOutput).slice(0, 200)
    }
  }];
}

// ============================================
// STEP 3 - CLEAN HTML
// Remove accidental markdown backticks
// ============================================
const cleanHtml = html
  .replace(/```html/gi, '')
  .replace(/```/g, '')
  .trim();

console.log('Clean HTML length:', cleanHtml.length);
console.log('Starts correctly:', cleanHtml.startsWith('<!DOCTYPE') || cleanHtml.startsWith('<html'));

// ============================================
// STEP 4 - READ METADATA FROM STATIC DATA
// No node name references needed
// ============================================
const staticData = $getWorkflowStaticData('global');
const category   = staticData.category || '';
const email      = staticData.email    || 'jeyaalagappan@gmail.com';

console.log('Category:', category);
console.log('Email:', email);

// ============================================
// STEP 5 - GENERATE FILENAME
// ============================================
const filename = `newsletter_${category.replace(/\s+/g, '_')}_${Date.now()}.html`;

console.log('Filename:', filename);

// ============================================
// STEP 6 - CONVERT TO BASE64
// ============================================
const base64 = Buffer.from(cleanHtml).toString('base64');

console.log('Base64 length:', base64.length);

// ============================================
// STEP 7 - RETURN HTML + BINARY ATTACHMENT
// ============================================
return [{
  json: {
    email,
    category,
    filename,
    html:       cleanHtml,
    htmlLength: cleanHtml.length,
    success:    true
  },
  binary: {
    attachment: {
      data:     base64,
      mimeType: 'text/html',
      fileName: filename
    }
  }
}];
